{
  "title": "Tính thể tích và diện tích xung quanh của hình nón",
  "description": "Bài toán này minh họa cách dựng hình nón từ đỉnh, tâm đáy và một điểm trên đường tròn đáy, sau đó tính thể tích và diện tích xung quanh của nó.",
  "memory_declarations": [
    {
      "name": "S",
      "type": "point3",
      "initial_value": [0, 0, 12],
      "source_fact_id": "s_coords",
      "label": "Đỉnh S của hình nón"
    },
    {
      "name": "O",
      "type": "point3",
      "initial_value": [0, 0, 0],
      "source_fact_id": "o_coords",
      "label": "Tâm đáy O của hình nón"
    },
    {
      "name": "A",
      "type": "point3",
      "initial_value": [5, 0, 0],
      "source_fact_id": "a_coords",
      "label": "Điểm A trên đường tròn đáy"
    },
    {
      "name": "khối nón",
      "type": "curved_solid",
      "label": "Khối nón cần tính thể tích"
    },
    {
      "name": "the_tich_khoi_non",
      "type": "float",
      "label": "Thể tích của khối nón"
    },
    {
      "name": "hình nón",
      "type": "curved_solid",
      "label": "Hình nón cần tính diện tích xung quanh"
    },
    {
      "name": "dien_tich_xung_quanh_hinh_non",
      "type": "float",
      "label": "Diện tích xung quanh của hình nón"
    }
  ],
  "statements": [
    {
      "kind": "construct_curved_solid",
      "target_var": "khối nón",
      "curved_kind": "cone",
      "apex_or_top": "S",
      "anchor": "O",
      "rim_point": "A",
      "label": "Dựng khối nón với đỉnh S, tâm đáy O và điểm A trên vành đáy"
    },
    {
      "kind": "assign",
      "target_var": "the_tich_khoi_non",
      "expr": {
        "kind": "measure",
        "quantity": "volume",
        "of": "khối nón"
      }
    },
    {
      "kind": "assign",
      "target_var": "hình nón",
      "expr": {
        "kind": "var",
        "name": "khối nón"
      }
    },
    {
      "kind": "assign",
      "target_var": "dien_tich_xung_quanh_hinh_non",
      "expr": {
        "kind": "measure",
        "quantity": "lateral_area",
        "of": "hình nón"
      }
    }
  ],
  "pedagogical_intent": "Chương trình này thể hiện cách định nghĩa một hình nón bằng các điểm cơ bản và sau đó sử dụng các phép đo tích hợp để tính toán các thuộc tính hình học của nó."
}
